language sql stable
as $$
  select exists (
    select 1
    from public.board_members
    where board_id = p_board_id and user_id = auth.uid()
  );
$$;

create function public.is_board_editor(p_board_id bigint) returns boolean
language sql stable
as $$
  select exists (
    select 1
    from public.board_members
    where board_id = p_board_id and user_id = auth.uid() and role = 'editor'
  );
$$;

create function public.board_is_not_archived(p_board_id bigint) returns boolean
language sql stable
as $$
  select exists (
    select 1
    from public.boards
    where id = p_board_id and is_archived = false
  );
$$;

create function public.can_manage_cards_on_board(p_board_id bigint) returns boolean
language sql stable
as $$
  select public.is_board_editor(p_board_id) and public.board_is_not_archived(p_board_id);
$$;

create policy boards_select on public.boards
for select to authenticated
using (public.is_board_member(id));

create policy board_members_select on public.board_members
for select to authenticated
using (public.is_board_member(board_id));

create policy cards_select on public.cards
for select to authenticated
using (public.is_board_member(board_id));

create policy cards_insert on public.cards
for insert to authenticated
with check (
  public.can_manage_cards_on_board(board_id)
  and (assignee_id is null or public.is_board_member(
    (select board_id from public.cards where id = new.id)
  ))
);

create policy cards_update on public.cards
for update to authenticated
using (
  public.can_manage_cards_on_board(board_id)
  and public.board_is_not_archived(board_id)
)
with check (
  public.can_manage_cards_on_board(board_id)
  and public.board_is_not_archived(board_id)
  and (assignee_id is null or public.is_board_member(
    (select board_id from public.cards where id = new.id)
  ))
);

create policy cards_delete on public.cards
for delete to authenticated
using (
  public.can_manage_cards_on_board(board_id)
  and public.board_is_not_archived(board_id)
);
