alter table public.friendships enable row level security;
alter table public.posts enable row level security;

create or replace function public.is_friend(p_user_id uuid)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.friendships f
    where (f.requester_id = p_user_id or f.addressee_id = p_user_id)
      and f.status = 'accepted'
  );
$$;

create or replace function public.is_own_post(p_post_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.posts p
    where p.id = p_post_id
      and p.author_id = auth.uid()
  );
$$;

create or replace function public.is_friend_or_own_post(p_post_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.posts p
    where p.id = p_post_id
      and (p.audience = 'public' or public.is_friend(p.author_id) or p.author_id = auth.uid())
  );
$$;

create policy friendships_select
on public.friendships
for select
to authenticated
using (
  requester_id = auth.uid()
  or addressee_id = auth.uid()
);

create policy friendships_insert
on public.friendships
for insert
to authenticated
with check (
  requester_id = auth.uid()
  and status = 'pending'
);

create policy friendships_update
on public.friendships
for update
to authenticated
using (
  status = 'pending'
  and addressee_id = auth.uid()
)
with check (
  status = 'accepted'
  and addressee_id = auth.uid()
);

create policy friendships_delete
on public.friendships
for delete
to authenticated
using (
  requester_id = auth.uid()
  or addressee_id = auth.uid()
);

create policy posts_select
on public.posts
for select
to anon
using (audience = 'public')
to authenticated
using (
  audience = 'public'
  or public.is_friend(author_id)
  or author_id = auth.uid()
);

create policy posts_insert
on public.posts
for insert
to authenticated
with check (
  author_id = auth.uid()
  and public.is_friend_or_own_post(id)
);

create policy posts_update
on public.posts
for update
to authenticated
using (
  author_id = auth.uid()
  and public.is_friend_or_own_post(id)
)
with check (
  author_id = auth.uid()
  and public.is_friend_or_own_post(id)
);

create policy posts_delete
on public.posts
for delete
to authenticated
using (
  author_id = auth.uid()
  and public.is_friend_or_own_post(id)
