    from jsonb_to_recordset(auth.jwt() -> 'amr') as x("method" text)
    where x.method = 'sso/saml'
  );
$$;

create function public.require_sso()
returns trigger
language plpgsql
as $$
declare
  v_org public.orgs;
  v_member public.org_members;
  v_bypass boolean;
begin
  select o, m, public.is_sso_session()
  into v_org, v_member, v_bypass
  from public.orgs o
  join public.org_members m on m.org_id = o.id
  where o.id = new.org_id
    and m.user_id = auth.uid()
  for update;

  if not found then
    raise exception 'unauthorized';
  end if;

  if v_org.require_sso and not v_bypass then
    raise exception 'sso required';
  end if;

  return new;
end
$$;

