```sql
alter table public.auctions enable row level security;
alter table public.bids enable row level security;

create policy auctions_select on public.auctions
  for select to authenticated
  using (true);

create policy bids_select on public.bids
  for select to authenticated
  using (
    bidder_id = auth.uid()
    or exists (
      select 1
      from public.auctions a
      where a.id = bids.auction_id
        and a.seller_id = auth.uid()
    )
  );

create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = public
as $$
declare
  v_auction public.auctions%rowtype;
  v_highest numeric(10, 2);
  v_min_increment numeric(10, 2);
  v_bidder uuid := auth.uid();
begin
  if v_bidder is null then
    raise exception 'not authenticated';
  end if;

  select * into v_auction
  from public.auctions
  where id = p_auction_id
  for update;

  if not found then
    raise exception 'auction not found';
  end if;

  if v_auction.seller_id = v_bidder then
    raise exception 'seller cannot bid on own auction';
  end if;

  if v_auction.ends_at <= now() then
    raise exception 'auction has ended';
  end if;

  if v_auction.highest_bid is null then
    v_highest := 0;
    v_min_increment := v_auction.min_increment;
  else
    v_highest := v_auction.highest_bid;
    v_min_increment := v_auction.min_increment;
  end if;

  if p_amount < v_auction.starting_price then
    raise exception 'bid below starting price';
  end if;

  if v_auction.highest_bid is null then
    if p_amount < v_auction.starting_price then
      raise exception 'bid below starting price';
    end if;
  else
    if p_amount < v_highest + v_min_increment then
      raise exception 'bid below highest bid plus minimum increment';
    end if;
  end if;

  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, v_bidder, p_amount, now());

  update public.auctions
  set highest_bid = p_amount,
      highest_bidder = v_bidder
  where id = p_auction_id;

  return p_amount;
end;
$$;

revoke all on public.auctions from anon;
revoke all on public.bids from anon;

revoke all on public.auctions from authenticated;
revoke all on public.bids from authenticated;

grant select on public.auctions to authenticated;
grant select on public.bids to authenticated;

grant execute on function public.place_bid(bigint, numeric) to authenticated;

grant all on public.auctions to service_role;
grant all on public.bids to service_role;

grant usage on sequence public.bids_id_seq to authenticated;
grant usage on sequence public.bids_id_seq to service_role;
```

