  using (
    bidder_id = auth.uid()
    or exists (select 1 from public.auctions a where a.id = bids.auction_id and a.seller_id = auth.uid())
  );

create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user uuid := auth.uid();
  v_auction public.auctions%rowtype;
begin
  if v_user is null then
    raise exception 'not authenticated';
  end if;

  select * into v_auction
  from public.auctions
  where id = p_auction_id
  for update;

  if not found or v_auction.ends_at <= now() then
    raise exception 'auction not found or ended';
  end if;

  if v_auction.seller_id = v_user then
    raise exception 'seller cannot bid on own auction';
  end if;

  if p_amount < 0 then
    raise exception 'bid amount must be non-negative';
  end if;

  if v_auction.highest_bid is null then
    if p_amount < v_auction.starting_price then
      raise exception 'bid below starting price';
    end if;
  else
    if p_amount < v_auction.highest_bid + v_auction.min_increment then
      raise exception 'bid below highest bid + minimum increment';
    end if;
  end if;

  update public.auctions
  set highest_bid = p_amount,
      highest_bidder = v_user
  where id = p_auction_id;

  insert into public.bids (auction_id, bidder_id, amount)
  values (p_auction_id, v_user, p_amount);

  return p_amount;
end;
